#!/usr/bin/env python3
# TCRM_FELFEL_REFERENCE_V7_PRESERVE_LIVE_V1
from __future__ import annotations
import argparse
import base64
import hashlib
from pathlib import Path
import zlib

TARGET = Path("client/src/pages/FelfelPage.tsx")
AVATAR = Path("client/public/ai-staff/felfel-avatar.webp")
EXPECTED_BASE_BLOB = "cd541f5ff161fad39ca0e98b0791917bca4243ac"
EXPECTED_TARGET_BLOB = "bc7fc40786d3c37944e5a51ebd33e0c6399cfddd"
EXPECTED_AVATAR_BLOB = "21e7557ee99908b5a9893bb5503d0e662c23d7b1"
PAYLOAD = (
""
""
""
""
)

def git_blob_sha(data: bytes) -> str:
    header = f"blob {len(data)}\0".encode("utf-8")
    return hashlib.sha1(header + data).hexdigest()

def payload_bytes() -> bytes:
    data = zlib.decompress(base64.b64decode(PAYLOAD))
    actual = git_blob_sha(data)
    if actual != EXPECTED_TARGET_BLOB:
        raise SystemExit(f"embedded payload hash mismatch: {actual}")
    return data

def current_blob(path: Path) -> str:
    if not path.is_file():
        return "MISSING"
    return git_blob_sha(path.read_bytes())

def check(require_base: bool) -> None:
    current = current_blob(TARGET)
    avatar = current_blob(AVATAR)
    print(f"FELFEL_PAGE_BLOB={current}")
    print(f"FELFEL_AVATAR_BLOB={avatar}")
    print(f"EXPECTED_BASE_BLOB={EXPECTED_BASE_BLOB}")
    print(f"EXPECTED_TARGET_BLOB={EXPECTED_TARGET_BLOB}")
    print(f"EXPECTED_AVATAR_BLOB={EXPECTED_AVATAR_BLOB}")
    if avatar != EXPECTED_AVATAR_BLOB:
        raise SystemExit("avatar blob is not the approved preserved avatar")
    if require_base and current != EXPECTED_BASE_BLOB:
        raise SystemExit("FelfelPage base does not match approved GitHub main; refusing to apply")

def apply() -> None:
    check(require_base=True)
    data = payload_bytes()
    TARGET.write_bytes(data)
    actual = current_blob(TARGET)
    if actual != EXPECTED_TARGET_BLOB:
        raise SystemExit(f"write verification failed: {actual}")
    print("APPLY=PASS")
    print(f"FELFEL_PAGE_BLOB={actual}")

def verify() -> None:
    check(require_base=False)
    current = current_blob(TARGET)
    if current != EXPECTED_TARGET_BLOB:
        raise SystemExit("FelfelPage is not the preserved live reference-v7 version")
    text = TARGET.read_text(encoding="utf-8")
    markers = [
        'data-felfel-uxui="reference-v7"',
        'object-[50%_18%]',
        'from-orange-600 to-orange-400',
        '<Puzzle className="h-5 w-5" />',
    ]
    missing = [m for m in markers if m not in text]
    if missing:
        raise SystemExit("missing visual markers: " + ", ".join(missing))
    print("VERIFY=PASS")

def main() -> None:
    parser = argparse.ArgumentParser()
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--check", action="store_true")
    group.add_argument("--apply", action="store_true")
    group.add_argument("--verify", action="store_true")
    args = parser.parse_args()
    if args.check:
        check(require_base=True)
        print("CHECK=PASS")
    elif args.apply:
        apply()
    else:
        verify()

if __name__ == "__main__":
    main()
